const header = document.querySelector('#header-section');
if (!header) return;
// Only move if not already right after the header
if (header.nextElementSibling === element) return;
header.parentNode.insertBefore(element, header.nextSibling);

element.style.display = 'flex';
element.style.flexDirection = 'row';
element.style.gap = '16px';
element.style.alignItems = 'flex-start';

// Make the post-player (left column) much bigger
const player = element.querySelector('.post-player');
if (player) {
  player.style.flex = '0 0 72%';
  player.style.maxWidth = '72%';
}

// Make bs-player fill its container
const bsPlayer = element.querySelector('bs-player');
if (bsPlayer) {
  bsPlayer.style.display = 'block';
  bsPlayer.style.width = '100%';
  bsPlayer.style.minHeight = '420px';
}

// Shrink the list column
const list = element.querySelector('.video-grid-franja-player-escuro__list');
if (list) {
  list.style.flex = '1 1 28%';
  list.style.maxWidth = '28%';
  list.style.overflowY = 'auto';
  list.style.maxHeight = '420px';
}
